/* app.js – quest list UI
 *
 *  A simple web app that lets you add quests, view them, and use an AI helper to
 *  suggest importance and type.  Data is persisted in localStorage via
 *  storage.js.
 *
 *  The UI contains:
 *    • Quests/Journal tab bar (Journal is a placeholder for now)
 *    • Selectable quest list; the right panel shows the selected quest and
 *      a "How to complete this" section generated by Ollama (cached in
 *      localStorage, with a Regenerate button)
 *    • Quest creation form (title, type, category, importance, tasks)
 *    • Settings section to choose AI provider and trigger a sort
 */

import { loadData, saveData, loadJournalEntries, saveJournalEntry } from './storage.js';
import { generateResponse } from './ai-helper.js';

const genId = () => '_' + Math.random().toString(36).slice(2, 11);

// Guidance panel state + cache (separate localStorage key, storage.js untouched)
let selectedQuestId = null;
const GUIDANCE_CACHE_KEY = 'guidanceCache';
function getGuidanceCache() {
  try {
    return JSON.parse(localStorage.getItem(GUIDANCE_CACHE_KEY)) || {};
  } catch {
    return {};
  }
}
function setGuidanceCache(cache) {
  localStorage.setItem(GUIDANCE_CACHE_KEY, JSON.stringify(cache));
}

// Fill the right column with a quest's details and Ollama-generated guidance.
function showQuestPanel(quest) {
  selectedQuestId = quest.id;
  const rightColumn = document.getElementById('right-column');
  rightColumn.innerHTML = '';

  const panel = createElement('div', { id: 'quest-panel' },
    createElement('h3', {}, quest.title),
    createElement('p', { id: 'quest-meta' },
      `Type: ${quest.kind}  ·  Category: ${quest.category}  ·  Importance: ${quest.importance}`
    ),
    createElement('h4', {}, 'How to complete this')
  );
  const guidanceEl = createElement('div', { id: 'guidance' }, 'thinking...');
  panel.appendChild(guidanceEl);
  const regenButton = createElement('button', { id: 'regenerate' }, 'Regenerate');
  regenButton.addEventListener('click', () => {
    const cache = getGuidanceCache();
    delete cache[quest.id];
    setGuidanceCache(cache);
    loadGuidance(quest); // back to the short version
  });
  panel.appendChild(regenButton);
  const thinkButton = createElement('button', { id: 'think-more' }, 'Think more');
  thinkButton.addEventListener('click', () => loadGuidance(quest, { long: true, useCache: false }));
  panel.appendChild(thinkButton);
  rightColumn.appendChild(panel);
  loadGuidance(quest);
}

// Always Ollama for the guidance panel, regardless of the settings bar provider.
// Short answer by default; { long: true } requests a fuller step-by-step plan.
// Both modes share the same per-quest cache entry (Think more replaces it).
async function loadGuidance(quest, { long = false, useCache = true } = {}) {
  const guidanceEl = document.getElementById('guidance');
  if (useCache) {
    const cache = getGuidanceCache();
    if (cache[quest.id]) {
      if (guidanceEl) guidanceEl.textContent = cache[quest.id];
      return;
    }
  }
  if (guidanceEl) guidanceEl.textContent = 'thinking...';
  const questDetails =
    `Quest title: ${quest.title}\n` +
    `Type: ${quest.kind}\n` +
    `Category: ${quest.category}\n` +
    `Importance: ${quest.importance}\n` +
    `Tasks:\n${(quest.tasks || []).join('\n') || '(none listed)'}\n\n`;
  const ask = long
    ? 'How can this person complete this task? Give a fuller step-by-step plan with practical details.'
    : 'How can this person complete this task? Give plain, practical guidance in 3 short sentences or fewer, no lists, no headings.';
  const messages = [{ role: 'user', content: questDetails + ask }];
  try {
    const text = await generateResponse(messages, 'ollama', undefined, {
      num_predict: long ? 500 : 120,
    });
    const c = getGuidanceCache();
    c[quest.id] = text;
    setGuidanceCache(c);
    if (selectedQuestId === quest.id && guidanceEl && guidanceEl.isConnected) {
      guidanceEl.textContent = text;
    }
  } catch (err) {
    if (guidanceEl && guidanceEl.isConnected) {
      guidanceEl.textContent =
        'Could not reach Ollama. Is it running at http://localhost:11434? (' + err.message + ')';
    }
  }
}

function selectQuest(quest) {
  document.querySelectorAll('#quest-list .quest-item').forEach(li =>
    li.classList.toggle('selected', li.dataset.questId === quest.id)
  );
  showQuestPanel(quest);
}

/* ------------------------------------------------------------------
 * Helper to create DOM elements with attributes and children
 * ------------------------------------------------------------------ */
function createElement(tag, attrs = {}, ...children) {
  const el = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs)) {
    if (key === 'textContent') {
      el.textContent = value;
    } else if (key.startsWith('on') && typeof value === 'function') {
      el.addEventListener(key.slice(2).toLowerCase(), value);
    } else {
      el.setAttribute(key, value);
    }
  }
  for (const child of children) {
    if (Array.isArray(child)) {
      child.forEach(n => el.appendChild(n));
    } else if (typeof child === 'string') {
      el.appendChild(document.createTextNode(child));
    } else {
      el.appendChild(child);
    }
  }
  return el;
}

function render() {
  const data = loadData();
  if (!data.player) data.player = {};
  if (!data.player.aiProvider) data.player.aiProvider = 'ollama';
  if (!data.quests) data.quests = [];

  const appDiv = document.getElementById('app');
  appDiv.innerHTML = '';

  const listContainer = createElement('div', { id: 'list-container' });
  const leftColumn = createElement('div', { id: 'left-column' });
  const rightColumn = createElement('div', { id: 'right-column' });
  leftColumn.appendChild(createElement('h2', {}, 'Quests')); // heading lives inside the left panel
  listContainer.appendChild(leftColumn);
  listContainer.appendChild(rightColumn);
  appDiv.appendChild(listContainer);

  // Quest creation form
  const form = createElement('form', { id: 'quest-form' },
    createElement('input', {
      type: 'text',
      id: 'title',
      placeholder: 'Quest title',
      required: true
    }),
    createElement('select', { id: 'kind' },
      createElement('option', { value: 'main' }, 'Main'),
      createElement('option', { value: 'side' }, 'Side')
    ),
    createElement('select', { id: 'category' },
      createElement('option', { value: 'School' }, 'School'),
      createElement('option', { value: 'Job' }, 'Job')
    ),
    createElement('select', { id: 'importance' },
      createElement('option', { value: 'low' }, 'Low'),
      createElement('option', { value: 'medium' }, 'Medium'),
      createElement('option', { value: 'high' }, 'High')
    ),
    createElement('textarea', {
      id: 'tasks',
      placeholder: 'Tasks (one per line)',
      rows: 3
    }),
    createElement('button', { type: 'submit' }, 'Add Quest')

  );
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const title = document.getElementById('title').value.trim();
    const kind = document.getElementById('kind').value;
    const category = document.getElementById('category').value;
    const importance = document.getElementById('importance').value;
    const tasksText = document.getElementById('tasks').value.trim();
    const tasks = tasksText ? tasksText.split('\n').map(t => t.trim()).filter(t => t) : [];
    if (!title) return;
    const newQuest = {
      id: genId(),
      title,
      kind,
      category,
      importance,
      tasks,
      status: 'todo',
      createdAt: Date.now()
    };
    data.quests.push(newQuest);
    saveData(data);
    form.reset();
    render();
  });
  const formContainer = createElement('div', { id: 'form-container' });
  formContainer.appendChild(form);

  // Quest list
  const list = createElement('ul', { id: 'quest-list' });
  data.quests.forEach(q => {
    const li = createElement('li',
      { 'class': 'quest-item', 'data-quest-id': q.id },
      createElement('strong', {}, q.title),
      ' ',
      createElement('span', {}, `[${q.kind}]`),
      ' ',
      createElement('span', {}, `(${q.importance})`),
      createElement('ul', {},
        q.tasks.map(t => createElement('li', {}, t))
      )
    );
    li.addEventListener('click', () => selectQuest(q));
    list.appendChild(li);
  });
  leftColumn.appendChild(list);

  // Restore the previously selected quest (panel was cleared by the re-render).
  if (selectedQuestId) {
    const selected = data.quests.find(q => q.id === selectedQuestId);
    if (selected) selectQuest(selected);
  }

  // Settings: AI provider selector and sort button
  const providerSelect = createElement('select', { id: 'provider-select' },
    createElement('option', { value: 'anthropic' }, 'Anthropic'),
    createElement('option', { value: 'ollama' }, 'Ollama')
  );
  providerSelect.value = data.player.aiProvider;
  providerSelect.addEventListener('change', (e) => {
    data.player.aiProvider = e.target.value;
    saveData(data);
    render();
  });

  const sortButton = createElement('button', { id: 'sort-quests' }, 'Sort Quests');
  sortButton.addEventListener('click', async () => {
    if (!data.quests.length) {
      alert('No quests to sort.');
      return;
    }
    const provider = data.player.aiProvider;
    const messages = [
      { role: 'system', content: 'You are a helpful quest organizer. For each quest, suggest an importance (low, medium, high) and type (main or side). Return a JSON object mapping quest ids to {type, importance}.' },
      { role: 'user', content: data.quests.map(q => `${q.id}: ${q.title}`).join('\n') }
    ];
    try {
      const raw = await generateResponse(messages, provider);
      // The model may sometimes return plain text. Try to parse JSON,
      // but if that fails we show the raw response to help debugging.
      let suggestions;
      try {
        suggestions = JSON.parse(raw);
      } catch (parseErr) {
        alert('AI returned non‑JSON. Raw response:\n' + raw);
        return;
      }
      data.quests.forEach(q => {
        const s = suggestions[q.id];
        if (s) {
          if (s.type && ['main', 'side'].includes(s.type)) q.kind = s.type;
          if (s.importance && ['low', 'medium', 'high'].includes(s.importance)) q.importance = s.importance;
        }
      });
      saveData(data);
      render();
      alert('Quests updated with AI suggestions.');
    } catch (err) {
      console.error(err);
      alert('Error fetching AI suggestions: ' + err.message);
    }
  });

  const settingsDiv = createElement('div', { id: 'settings' },
    createElement('label', { for: 'provider-select' }, 'AI Provider: '),
    providerSelect,
    sortButton
  );
  // Form intentionally lives at the bottom of the page.
  settingsDiv.insertBefore(formContainer, settingsDiv.firstChild);

  // Clear the placeholder first so re-renders don't stack duplicate
  // settings bars.
  const settingsPlaceholder = document.getElementById('settings-placeholder');
  if (settingsPlaceholder) {
    settingsPlaceholder.innerHTML = '';
    settingsPlaceholder.appendChild(settingsDiv);
  } else {
    appDiv.appendChild(settingsDiv);
  }
}

// Tab switching: show one panel at a time, mark the active tab.
function switchTab(name) {
  ['quests', 'journal'].forEach(tabName => {
    const panel = document.getElementById('panel-' + tabName);
    const tab = document.getElementById('tab-' + tabName);
    if (panel) panel.hidden = tabName !== name;
    if (tab) tab.classList.toggle('active', tabName === name);
  });
}
document.getElementById('tab-quests').addEventListener('click', () => switchTab('quests'));
document.getElementById('tab-journal').addEventListener('click', () => switchTab('journal'));

// Journal tab: past entries, newest first; clicking one loads its full text.
function renderJournalList() {
  const list = document.getElementById('journal-list');
  list.innerHTML = '';
  const entries = loadJournalEntries().slice().sort((a, b) => b.savedAt - a.savedAt);
  entries.forEach(e => {
    const firstLine = (e.text.split('\n')[0] || '').trim() || '(empty)';
    const li = createElement('li', { class: 'journal-entry' },
      new Date(e.savedAt).toLocaleString() + '  —  ' + firstLine
    );
    li.addEventListener('click', () => {
      document.getElementById('journal-text').value = e.text;
    });
    list.appendChild(li);
  });
}
document.getElementById('journal-save').addEventListener('click', () => {
  const ta = document.getElementById('journal-text');
  const text = ta.value.trim();
  if (!text) return;
  saveJournalEntry(text);
  ta.value = '';
  renderJournalList();
});
renderJournalList();

// Initial render when the page loads
render();
